<?php
declare(strict_types=1); require_once __DIR__.'/_helper.php';
$id=(int)($_GET['id']??0);$s=absensi_find_session($pdo,$id);if(!$s) {http_response_code(404);exit('Sesi tidak ditemukan.');}
auto_sync_session_lifecycle($pdo,$id);
$s=absensi_find_session($pdo,$id);
$notice='Status sesi diperbarui otomatis berdasarkan jadwal WIB.';
$jamMulaiPulang=absensi_setting_value($pdo,'jam_mulai_pulang','13:00') ?? '13:00';
