$batasFinalisasi=absensi_batas_finalisasi($pdo);
$st=$pdo->prepare("SELECT a.*,s.nama,s.nis FROM absensi a JOIN siswa s ON s.id=a.siswa_id WHERE a.sesi_id=? ORDER BY a.waktu_scan DESC,a.id DESC LIMIT 100");$st->execute([$id]);$scanRows=$st->fetchAll();
$page_title='Detail Sesi';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Detail Sesi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content attendance-detail-module"><div class="page-header"><div><h1><?=e($s['nama_sesi'])?></h1><p><?=e($s['tanggal'])?> · <?=e($s['jenis_nama'])?><?php if($s['sholat_nama']):?> · <?=e($s['sholat_nama'])?><?php endif;?></p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/index.php">Kembali</a><?php if($s['kategori']==='kehadiran'):?><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/daftar.php?sesi_id=<?=$id?>">Kehadiran</a><?php elseif($s['kategori']==='sholat'):?><a class="btn btn-secondary" href="<?=BASE_URL?>sholat/daftar.php?sesi_id=<?=$id?>">Kehadiran Sholat</a><?php endif;?><?php if(($s['status_sesi']??'')!=='CLOSED'):?><a class="btn btn-primary" href="<?=BASE_URL?>scanner/index.php?sesi_id=<?=$id?>">Buka Scanner</a><?php endif;?></div></div><?php if($notice):?><div class="alert alert-info"><?=e($notice)?></div><?php endif;?><div class="form-card"><div class="detail-grid"><div><small>Status Sesi</small><strong><span class="status-badge status-<?= (($s['status_sesi']??'DRAFT')==='OPEN'?'aktif':(($s['status_sesi']??'DRAFT')==='CLOSED'?'ditutup':'draft')) ?>"><?=e((string)($s['status_sesi']??'DRAFT'))?></span></strong></div><div><small>Tahun Pelajaran</small><strong><?=e($s['tahun_nama'])?></strong></div><div><small>Semester</small><strong><?=e($s['semester_nama'])?></strong></div><div><small>Jam Datang (sesi ini)</small><strong><?=e(substr($s['jam_mulai'],0,5))?>–<?=e(substr($s['jam_selesai'],0,5))?></strong></div><?php if($s['kategori']==='kehadiran'): ?><div><small>Jadwal Absen Pulang</small><strong><?=e($jamMulaiPulang)?>–<?=e($jamSelesaiPulang)?> WIB</strong></div><div><small>Batas Finalisasi Otomatis</small><strong><?=e($batasFinalisasi)?> WIB</strong></div><?php endif; ?><div><small>Batas Terlambat</small><strong><?=e($s['batas_terlambat']?substr($s['batas_terlambat'],0,5):'-')?></strong></div><div><small>Jumlah Scan</small><strong><?=count($scanRows)?></strong></div><?php if($s['kategori']==='kehadiran'): ?><div><small>Final Kehadiran</small><strong><?=!empty($s['finalisasi_at'])?'🔒 FINAL':'Belum Final'?></strong></div><?php endif; ?></div><div class="info-box"><strong>Lifecycle otomatis.</strong><p>DRAFT sebelum jam mulai, OPEN selama jadwal berlangsung, dan CLOSED setelah jam selesai. Operator tidak perlu membuka atau menutup sesi secara manual.</p></div></div><div class="dashboard-table-card"><div class="section-title"><div><h2>Transaksi Scan</h2><p>Maksimal 100 transaksi terakhir.</p></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Waktu</th><th>NIS</th><th>Nama</th><th>Status</th><th>Keterangan</th></tr></thead><tbody><?php if(!$scanRows):?><tr><td colspan="5" class="empty-state">Belum ada scan.</td></tr><?php else:foreach($scanRows as $r):?><tr><td><?=e((string)$r['waktu_scan'])?></td><td><?=e($r['nis'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['status'])?></td><td><?=e((string)($r['keterangan']??''))?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
